    // Generate DSA parameters using OpenSSL C API
    DSA *dsa = DSA_new();
    if (!dsa) {
        return "";
    }

    // Generate DSA parameters with 2048 bits
    if (!DSA_generate_parameters_ex(dsa, 2048, NULL, 0, NULL, 0, NULL)) {
        ERR_print_errors_fp(stderr);
        DSA_free(dsa);
        return "";
    }

    // Generate private key
    if (!DSA_generate_key(dsa)) {
        ERR_print_errors_fp(stderr);
        DSA_free(dsa);
        return "";
    }

    // Convert DSA to PEM format
    BIO *bio = BIO_new(BIO_s_mem());
    if (!PEM_write_bio_DSA_PUBKEY(bio, dsa) || !PEM_write_bio_DSA_PrivateKey(bio, dsa)) {
        ERR_print(errors, stderr);
        DSA_free(dsa);
        return "";
    }

    // Get the PEM string
    char *pem_data;
    long pem_len = BIO_get_mem_data(bio, &pem_data);
    std::string pem_str(pem_data, pem_len);

    // Clean up
    BIO_free(bio);
    DSA_free(dsa);

    return pem_str;
